import "server-only";
import { tmdbFetch } from "./client";
import type { TmdbMovieDetail, TmdbMovieListResponse } from "./models";

export function getMovies(page = 1) {
  return tmdbFetch<TmdbMovieListResponse>("movie/popular", { page });
}

export function getMovieDetail(movieId: number) {
  return tmdbFetch<TmdbMovieDetail>(`movie/${movieId}`);
}

export function searchMovies(query: string, page = 1) {
  return tmdbFetch<TmdbMovieListResponse>("search/movie", {
    query,
    include_adult: false,
    page,
  });
}
