import Link from "next/link";

interface PaginationProps {
  currentPage: number;
  totalPages: number;
}

const MAX_PAGE = 500; // TMDB가 허용하는 최대 페이지

const baseClass = "inline-flex h-9 min-w-9 items-center justify-center rounded-lg border px-3 text-sm font-semibold";
const disabledClass = "cursor-not-allowed opacity-40";

function pageHref(page: number) {
  return page === 1 ? "/" : `/?page=${page}`;
}

// 페이지 번호를 URL(?page=)로 관리하는 Server Component예요.
export default function Pagination({ currentPage, totalPages }: PaginationProps) {
  const lastPage = Math.min(totalPages, MAX_PAGE);
  if (lastPage <= 1) return null;

  const startPage = Math.max(1, Math.min(currentPage - 2, lastPage - 4));
  const pages = Array.from({ length: Math.min(5, lastPage) }, (_, i) => startPage + i);

  return (
    <nav aria-label="영화 목록 페이지" className="mt-10 flex justify-center gap-2">
      {currentPage === 1 ? (
        <span aria-disabled="true" className={`${baseClass} ${disabledClass}`}>이전</span>
      ) : (
        <Link href={pageHref(currentPage - 1)} className={baseClass}>이전</Link>
      )}

      {pages.map((page) => (
        <Link
          key={page}
          href={pageHref(page)}
          aria-current={currentPage === page ? "page" : undefined}
          className={`${baseClass} ${
            currentPage === page
              ? "border-indigo-600 bg-indigo-600 text-white"
              : "border-gray-200 bg-white text-gray-600 hover:bg-gray-100"
          }`}
        >
          {page}
        </Link>
      ))}

      {currentPage === lastPage ? (
        <span aria-disabled="true" className={`${baseClass} ${disabledClass}`}>다음</span>
      ) : (
        <Link href={pageHref(currentPage + 1)} className={baseClass}>다음</Link>
      )}
    </nav>
  );
}
