import type { TmdbMovieListItem } from "@/lib/tmdb/models";
import MovieCard from "./movie-card";

export default function MovieGrid({ movies }: { movies: TmdbMovieListItem[] }) {
  return (
    <section className="grid grid-cols-1 gap-4 sm:grid-cols-2 sm:gap-5 lg:grid-cols-3 xl:grid-cols-5">
      {movies.map((movie) => (
        <MovieCard key={movie.id} movie={movie} />
      ))}
    </section>
  );
}
