import type { Metadata } from "next";
import { Suspense } from "react";
import { getMovies } from "@/lib/tmdb/movies";
import MovieGrid from "@/components/movies/movie-grid";
import Pagination from "@/components/movies/pagination";
import StatusMessage from "@/components/ui/status-message";

export const metadata: Metadata = { title: "영화 목록" };

interface HomePageProps {
  searchParams: Promise<{ page?: string | string[] }>;
}

// 제목은 빌드 때 미리 만들고, 목록은 요청 시 서버에서 준비해요(Partial Prerendering).
export default function HomePage({ searchParams }: HomePageProps) {
  return (
    <main className="mx-auto min-h-[calc(100vh-73px)] w-full max-w-7xl px-4 py-8 sm:px-6 sm:py-10">
      <h1 className="mb-7 text-2xl font-extrabold tracking-tight text-gray-950 sm:text-3xl">영화 목록</h1>
      <Suspense fallback={<StatusMessage>영화를 불러오는 중이에요.</StatusMessage>}>
        <MovieList searchParams={searchParams} />
      </Suspense>
    </main>
  );
}

async function MovieList({ searchParams }: HomePageProps) {
  const { page: rawPage } = await searchParams;
  const parsed = Number(Array.isArray(rawPage) ? rawPage[0] : rawPage);
  const page = Number.isInteger(parsed) && parsed >= 1 ? Math.min(parsed, 500) : 1;

  const { results, total_pages } = await getMovies(page);

  if (results.length === 0) {
    return <p className="py-12 text-center text-gray-500">표시할 영화가 없어요.</p>;
  }

  return (
    <>
      <MovieGrid movies={results} />
      <Pagination currentPage={page} totalPages={total_pages} />
    </>
  );
}
